"""Task-local inspection: locate .db files in the workspace and report their schema."""
import os
import sqlite3
import sys


def find_db_files(root="."):
    matches = []
    for dirpath, dirnames, filenames in os.walk(root):
        # Skip common virtualenv / cache dirs to keep output focused
        dirnames[:] = [
            d
            for d in dirnames
            if d not in (".venv", "venv", "__pycache__", ".git", ".tox")
        ]
        for name in filenames:
            if name.lower().endswith(".db") or name.lower().endswith(".sqlite3"):
                matches.append(os.path.join(dirpath, name))
    return matches


def describe_db(path):
    print(f"=== {path} ===")
    with sqlite3.connect(path) as conn:
        cur = conn.cursor()
        cur.execute("SELECT name, type FROM sqlite_master WHERE type IN ('table','view') ORDER BY name")
        objects = cur.fetchall()
        if not objects:
            print("  (no tables or views)")
        for name, obj_type in objects:
            print(f"  {obj_type}: {name}")
            if obj_type == "table":
                cur.execute(f"PRAGMA table_info({name})")
                for col in cur.fetchall():
                    cid, cname, ctype, notnull, dflt, pk = col
                    print(f"    - {cname} {ctype} pk={pk} notnull={notnull} default={dflt}")


def main():
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    print("Files in workspace:")
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [
            d
            for d in dirnames
            if d not in (".venv", "venv", "__pycache__", ".git", ".tox")
        ]
        for name in filenames:
            print(f"  {os.path.join(dirpath, name)}")

    dbs = find_db_files(root)
    print("\nDatabase files found:", dbs or "none")
    for db in dbs:
        describe_db(db)


if __name__ == "__main__":
    main()

"""Unit tests for login.py, run against a temporary SQLite database.

The test schema mirrors the ``users`` table in ``user_credentials.db``
so the tests exercise the same columns the real script inserts into.
"""

import tempfile
import unittest
from pathlib import Path

import login

SCHEMA = """
CREATE TABLE users (
    id INTEGER PRIMARY KEY,
    username TEXT NOT NULL,
    email TEXT NOT NULL,
    password_hash TEXT NOT NULL,
    created_date TEXT NOT NULL,
    access_rights TEXT DEFAULT 'user'
);
"""


class LoginTests(unittest.TestCase):
    def setUp(self):
        self.tmpdir = tempfile.TemporaryDirectory()
        self.db_path = Path(self.tmpdir.name) / "test_users.db"
        with login.connect(self.db_path) as conn:
            conn.execute(SCHEMA)

    def tearDown(self):
        self.tmpdir.cleanup()

    def test_register_then_login(self):
        login.register_user(
            "alice", "alice@example.com", "correct-horse", db_path=self.db_path
        )
        row = login.authenticate("alice", "correct-horse", db_path=self.db_path)
        self.assertIsNotNone(row)
        self.assertEqual(row["username"], "alice")
        self.assertEqual(row["access_rights"], "user")

    def test_login_username_is_case_insensitive(self):
        login.register_user(
            "Bob", "bob@example.com", "hunter2password", db_path=self.db_path
        )
        self.assertIsNotNone(
            login.authenticate("bob", "hunter2password", db_path=self.db_path)
        )

    def test_duplicate_username_rejected(self):
        login.register_user(
            "alice", "alice@example.com", "password-one", db_path=self.db_path
        )
        with self.assertRaises(ValueError):
            login.register_user(
                "ALICE", "other@example.com", "password-two", db_path=self.db_path
            )

    def test_duplicate_email_rejected(self):
        login.register_user(
            "alice", "alice@example.com", "password-one", db_path=self.db_path
        )
        with self.assertRaises(ValueError):
            login.register_user(
                "bob", "alice@example.com", "password-two", db_path=self.db_path
            )

    def test_wrong_password_rejected(self):
        login.register_user(
            "alice", "alice@example.com", "password-one", db_path=self.db_path
        )
        self.assertIsNone(
            login.authenticate("alice", "password-two", db_path=self.db_path)
        )

    def test_unknown_user_rejected(self):
        self.assertIsNone(login.authenticate("nobody", "whatever", db_path=self.db_path))

    def test_password_not_stored_in_plaintext(self):
        password = "super-secret-42"
        login.register_user(
            "alice", "alice@example.com", password, db_path=self.db_path
        )
        with login.connect(self.db_path) as conn:
            stored = conn.execute(
                "SELECT password_hash FROM users WHERE username = ?", ("alice",)
            ).fetchone()[0]
        self.assertNotEqual(stored, password)
        self.assertTrue(stored.startswith("pbkdf2_sha256$"))
        self.assertNotIn(password, stored)

    def test_short_password_rejected(self):
        with self.assertRaises(ValueError):
            login.register_user(
                "alice", "alice@example.com", "short", db_path=self.db_path
            )

    def test_invalid_email_rejected(self):
        with self.assertRaises(ValueError):
            login.register_user(
                "alice", "not-an-email", "long-enough-password", db_path=self.db_path
            )


if __name__ == "__main__":
    unittest.main()

